"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[7142],{7142:a=>{a.exports=JSON.parse('{"meta":{"title":"Sokongan & Soalan Lazim - iMuslim Life","description":"Dapatkan jawapan kepada soalan lazim tentang waktu solat dan ciri iMuslim Life, serta dapatkan sokongan."},"heading":"Soalan Lazim & Sokongan","items":[{"q":"Bagaimanakah waktu solat dikira?","a":"Kami menggunakan kaedah pengiraan yang sangat tepat berdasarkan formula astronomi. Anda boleh memilih pelbagai kaedah pengiraan dalam tetapan supaya sepadan dengan masjid tempatan atau pilihan anda."},{"q":"Adakah data lokasi saya disimpan?","a":"Privasi anda keutamaan kami. Data lokasi hanya digunakan buat sementara untuk mendapatkan waktu solat dan tidak disimpan di pelayan kami, kecuali anda sendiri menyimpan sesuatu lokasi."},{"q":"Bolehkah saya menggunakan aplikasi ini di luar talian?","a":"Ciri asas seperti pembaca al-Quran mungkin berfungsi di luar talian jika telah dimuatkan sebelum ini. Namun, mendapatkan waktu solat untuk lokasi atau tarikh baharu memerlukan sambungan internet."},{"q":"Bagaimanakah saya boleh melaporkan masalah atau mencadangkan ciri?","a":"Kami gembira mendengar daripada anda! Gunakan butang hubungi di bawah atau hubungi kami melalui saluran sokongan yang dinyatakan dalam bahagian hubungi."},{"q":"Adakah aplikasi ini percuma sepenuhnya?","a":"Ya, iMuslim Life 100% percuma dan tanpa iklan. Matlamat kami ialah menyediakan alat Islam yang penting untuk semua orang."}],"contact":{"title":"Perlukan Bantuan Lagi?","text":"Jika anda tidak menemui jawapan di sini, jangan segan menghubungi pasukan sokongan kami.","button":"Hubungi Sokongan"}}')}}]);